import Foundation

/// Which screen the wallet is on, decided by the core's state, not a navigation stack.
enum Stage: Equatable {
    case opening
    case needsWallet
    case showingPhrase
    case restoring
    case locked
    /// Locked, and the key that sealed the vault is gone from this device.
    case keyGone
    case ready
    case measuring
    /// What is in the app and under what licence, generated by the build.
    case showingLicences
}

/// What long call is in flight.
enum Busy: Equatable {
    case idle
    case unlocking
    case syncing
    /// Reading the pool before a deposit is built.
    case depositing
    case proving
    case cancelling
    /// Reading the public account, or working out a send before signing it.
    case reading
    case reviewing
    case sending
    /// Handing a proved spend to the lander over its onion service.
    case handing
    case measuring
    /// What is in the app and under what licence, generated by the build.
    case showingLicences
    /// After a restore, looking for the other accounts the words were used with.
    case finding
}
